CREATE DEFINER=`root`@`localhost` PROCEDURE `BorrowBook` (IN `p_student_id` INT, IN `p_account_id` INT, IN `p_book_id` INT, IN `p_date_borrow` DATE, IN `p_date_due` DATE)   BEGIN
    DECLARE v_currentBorrowed INT DEFAULT 0;
    DECLARE v_quantity INT;
    DECLARE v_title VARCHAR(255);

    -- Handler for any SQL error
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 'error' AS status, 'Transaction failed, rolled back' AS message;
    END;

    START TRANSACTION;

    -- 1. Count current borrowed books
    SELECT COUNT(bd.book_id) INTO v_currentBorrowed
    FROM borrow b
    JOIN borrow_details bd ON b.borrow_id = bd.borrow_id
    WHERE b.student_id = p_student_id AND b.status='Borrowed';

    -- 2. Limit: max 3 books
    IF v_currentBorrowed >= 3 THEN
        ROLLBACK;
        SELECT 'error' AS status, 'Cannot borrow more than 3 books per student.' AS message;
    ELSE
        -- 3. Check if book is available
        SELECT quantity, title INTO v_quantity, v_title
        FROM books
        WHERE book_id = p_book_id
        FOR UPDATE;

        IF v_quantity IS NULL OR v_quantity <= 0 THEN
            ROLLBACK;
            SELECT 'error' AS status, CONCAT('Book unavailable: ', v_title) AS message;
        ELSE
            -- 4. Insert main borrow record
            INSERT INTO borrow(student_id, account_id, date_borrow, date_due, status, created_at)
            VALUES(p_student_id, p_account_id, p_date_borrow, p_date_due, 'Borrowed', NOW());

            SET @borrow_id = LAST_INSERT_ID();

            -- 5. Insert borrow_details
            INSERT INTO borrow_details(borrow_id, book_id, quantity)
            VALUES(@borrow_id, p_book_id, 1);

            -- 6. Reduce book quantity
            UPDATE books
            SET quantity = quantity - 1
            WHERE book_id = p_book_id;

            COMMIT;

            SELECT 'success' AS status, 'Book borrowed successfully.' AS message;
        END IF;
    END IF;

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_book` (IN `p_cover` VARCHAR(255), IN `p_title` VARCHAR(255), IN `p_author` VARCHAR(255), IN `p_isbn` VARCHAR(50), IN `p_genre` VARCHAR(100), IN `p_location` VARCHAR(100), IN `p_availability` VARCHAR(50), IN `p_quantity` INT, IN `p_total_quantity` INT, IN `p_publisher` VARCHAR(255), IN `p_description` TEXT)   BEGIN
    INSERT INTO books 
    (cover, title, author, isbn, genre, location, availability, quantity, total_quantity, publisher, description)
    VALUES
    (p_cover, p_title, p_author, p_isbn, p_genre, p_location, p_availability, p_quantity, p_total_quantity, p_publisher, p_description);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_student` (IN `p_fname` VARCHAR(100), IN `p_lname` VARCHAR(100), IN `p_student_number` INT, IN `p_section_name` VARCHAR(100), IN `p_year` INT, IN `p_course_id` INT)   BEGIN
    DECLARE v_section_id INT;

    -- check if section exists
    SELECT section_id INTO v_section_id
    FROM section
    WHERE section_name = p_section_name
      AND year_level = p_year
      AND course_id = p_course_id
    LIMIT 1;

    -- if not exists, insert
    IF v_section_id IS NULL THEN
        INSERT INTO section (section_name, course_id, year_level)
        VALUES (p_section_name, p_course_id, p_year);

        SET v_section_id = LAST_INSERT_ID();
    END IF;

    -- insert student
    INSERT INTO student (fname, lname, student_number, section_id)
    VALUES (p_fname, p_lname, p_student_number, v_section_id);

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `return_book` (IN `p_borrow_id` INT, IN `p_account_id` INT)   BEGIN

    DECLARE v_return_date DATE;

    -- set today as return date
    SET v_return_date = CURDATE();

    -- 1. update borrow table
    UPDATE borrow
    SET 
        status = 'Returned',
        return_date = v_return_date,
        account_id = p_account_id
    WHERE borrow_id = p_borrow_id;

    -- 2. return all books (increase quantity)
    UPDATE books b
    JOIN borrow_details bd ON b.book_id = bd.book_id
    SET b.quantity = b.quantity + 1
    WHERE bd.borrow_id = p_borrow_id;

    -- 3. optional: update availability
    UPDATE books
    SET availability = 'Available'
    WHERE quantity > 0
    AND book_id IN (
        SELECT book_id FROM borrow_details WHERE borrow_id = p_borrow_id
    );

END$$

